css:
.button-stack,
.button-stack * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, sans-serif;
}

.button-stack {
  display: flex;
  flex-direction: column;
  gap: 2.5em;
  padding: 2.5em;
  align-items: center;
}

.btn-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
  opacity: 0;
  animation: floatIn 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.btn-wrapper:nth-child(1) {
  animation-delay: 0.1s;
}
.btn-wrapper:nth-child(2) {
  animation-delay: 0.25s;
}
.btn-wrapper:nth-child(3) {
  animation-delay: 0.4s;
}

@keyframes floatIn {
  0% {
    opacity: 0;
    transform: translateY(30px) scale(0.9);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.btn-wrapper:hover {
  z-index: 10;
}

.orb-btn {
  position: relative;
  width: 5em;
  height: 5em;
  border-radius: 50%;
  background: transparent;
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  border: none;
  outline: none;
  background: radial-gradient(
    circle at 50% 50%,
    rgba(0, 0, 0, 0.1) 0%,
    rgba(var(--glow-color), 0.08) 50%,
    rgba(var(--glow-color), 0.35) 100%
  );
  box-shadow:
    inset 0 0 25px 2px rgba(var(--glow-color), 0.35),
    inset 0 0 8px 1px rgba(var(--glow-color), 0.6),
    0 0 35px 2px rgba(var(--glow-color), 0.25);
  transition:
    transform 0.4s cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 0.4s cubic-bezier(0.2, 0.8, 0.2, 1);
  -webkit-tap-highlight-color: transparent;
  overflow: hidden;
}

.orb-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.25) 0%,
    transparent 40%,
    rgba(0, 0, 0, 0.5) 100%
  );
  pointer-events: none;
  z-index: 0;
  box-shadow: inset 1px 2px 4px rgba(255, 255, 255, 0.4);
}

.orb-btn::after {
  content: "";
  position: absolute;
  top: 0;
  left: -150%;
  width: 50%;
  height: 100%;
  background: linear-gradient(
    to right,
    rgba(255, 255, 255, 0) 0%,
    rgba(255, 255, 255, 0.3) 50%,
    rgba(255, 255, 255, 0) 100%
  );
  transform: skewX(-25deg);
  z-index: 1;
  pointer-events: none;
}

.btn-wrapper:hover .orb-btn::after {
  animation: shimmerSweep 0.8s ease-out forwards;
}

@keyframes shimmerSweep {
  0% {
    left: -150%;
  }
  100% {
    left: 200%;
  }
}

.btn-wrapper:hover .orb-btn {
  transform: scale(1.06);
  box-shadow:
    inset 0 0 30px 4px rgba(var(--glow-color), 0.45),
    inset 0 0 12px 2px rgba(var(--glow-color), 0.7),
    0 0 50px 8px rgba(var(--glow-color), 0.35);
}

.btn-wrapper:active .orb-btn {
  transform: scale(0.92);
  box-shadow:
    inset 0 0 35px 5px rgba(var(--glow-color), 0.8),
    inset 0 0 15px 4px rgba(255, 255, 255, 0.7),
    0 0 30px 5px rgba(var(--glow-color), 0.4);
}

.orb-btn svg {
  width: 2.125em;
  height: 2.125em;
  stroke: #ffffff;
  stroke-width: 1;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  z-index: 2;
  filter: drop-shadow(0 0 3px rgba(255, 255, 255, 0.3));
  transition: all 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.btn-wrapper:hover .btn-teal svg {
  transform: scale(1.15) rotate(180deg);
}

@keyframes arrowFly {
  0% {
    transform: translate(0, 0);
    opacity: 1;
  }
  40% {
    transform: translate(20px, -20px);
    opacity: 0;
  }
  41% {
    transform: translate(-20px, 20px);
    opacity: 0;
  }
  100% {
    transform: translate(3px, -3px);
    opacity: 1;
  }
}

.btn-wrapper:hover .btn-silver svg {
  animation: arrowFly 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.btn-mauve svg path {
  stroke-dasharray: 40;
  stroke-dashoffset: 0;
  transition: stroke-dashoffset 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes drawCheck {
  0% {
    stroke-dashoffset: 40;
  }
  100% {
    stroke-dashoffset: 0;
  }
}

.btn-wrapper:hover .btn-mauve svg {
  transform: scale(1.25);
}

.btn-wrapper:hover .btn-mauve svg path {
  animation: drawCheck 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.btn-label {
  position: absolute;
  left: 100%;
  margin-left: -0.3125em;
  opacity: 0;
  color: rgba(255, 255, 255, 0.9);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 3px;
  text-transform: uppercase;
  white-space: nowrap;
  pointer-events: none;
  transition: all 0.6s cubic-bezier(0.16, 1, 0.3, 1);
  transform: translateX(-10px) scale(0.95);
  filter: blur(8px);
  text-shadow: 0 4px 15px rgba(0, 0, 0, 0.6);
}

.btn-wrapper:hover .btn-label {
  margin-left: 2.5em;
  opacity: 1;
  transform: translateX(0) scale(1);
  filter: blur(0px);
  letter-spacing: 5px;
}

.btn-teal {
  --glow-color: 52, 142, 150;
}

.btn-silver {
  --glow-color: 180, 195, 210;
}

.btn-mauve {
  --glow-color: 188, 108, 148;
}
